part of '../main.dart';

class ScoreChip extends StatelessWidget {final int score;const ScoreChip({super.key,required this.score});@override Widget build(BuildContext context)=>Container(padding:const EdgeInsets.symmetric(horizontal:12,vertical:7),decoration:BoxDecoration(color:orange,borderRadius:BorderRadius.circular(20)),child:Row(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.bolt_rounded,size:17,color:navy),Text('$score',style:const TextStyle(color:navy,fontWeight:FontWeight.w900))]));}
class MenuTile extends StatelessWidget {final IconData icon;final String label;final VoidCallback onTap;const MenuTile({super.key,required this.icon,required this.label,required this.onTap});@override Widget build(BuildContext context)=>Card(child:InkWell(borderRadius:BorderRadius.circular(16),onTap:onTap,child:Padding(padding:const EdgeInsets.symmetric(vertical:18,horizontal:10),child:Column(children:[Icon(icon,color:cyan,size:30),const SizedBox(height:8),Text(label,style:const TextStyle(fontSize:12,fontWeight:FontWeight.w900))]))));}
class AppTitle extends StatelessWidget {final String title,subtitle;const AppTitle(this.title,this.subtitle,{super.key});@override Widget build(BuildContext context)=>Row(children:[IconButton.filledTonal(onPressed:()=>Navigator.pop(context),icon:const Icon(Icons.arrow_back_rounded)),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:const TextStyle(fontSize:20,fontWeight:FontWeight.w900)),Text(subtitle,style:const TextStyle(color:Color(0xFF9DB5C8),fontSize:12))]))]);}

class Mascot extends StatelessWidget {final String name;final double size;const Mascot({super.key,required this.name,this.size=90});@override Widget build(BuildContext context){final pixel=name=='PIXEL';return Container(width:size,height:size,decoration:BoxDecoration(shape:BoxShape.circle,color:pixel?orange:cyan,border:Border.all(color:cream,width:4),boxShadow:[BoxShadow(color:(pixel?orange:cyan).withValues(alpha:.25),blurRadius:30)]),child:Stack(alignment:Alignment.center,children:[Icon(pixel?Icons.memory_rounded:Icons.router_rounded,size:size*.5,color:navy),Positioned(bottom:size*.16,left:size*.24,child:Container(width:size*.12,height:size*.08,decoration:BoxDecoration(color:navy,borderRadius:BorderRadius.circular(9)))),Positioned(bottom:size*.16,right:size*.24,child:Container(width:size*.12,height:size*.08,decoration:BoxDecoration(color:navy,borderRadius:BorderRadius.circular(9))))]));}}
